package com.ledgerbase.backend.model;

import java.time.LocalDate;
import java.time.OffsetDateTime;

/**
 * Represents the header of a financial transaction.
 *
 * This maps to the PostgreSQL "transactions" table.
 *
 * A transaction can have multiple ledger entries,
 * which we'll model separately.
 */
public class LedgerTransaction {

    // Primary key generated by PostgreSQL.
    private Long id;

    // Business that owns the transaction.
    private Long businessId;

    // User who created the transaction.
    private Long createdBy;

    // Optional classification and counterparties.
    private Long categoryId;
    private Long customerId;
    private Long vendorId;

    // Description of the financial activity.
    private String description;

    // Accounting date (e.g., 2026-10-11).
    private LocalDate transactionDate;

    // Lifecycle state, such as DRAFT or POSTED.
    private String status;

    // Timestamp when PostgreSQL created the record.
    private OffsetDateTime createdAt;

    public Long getId() {
        return id;
    }

    public void setId(Long id) {
        this.id = id;
    }

    public Long getBusinessId() {
        return businessId;
    }

    public void setBusinessId(Long businessId) {
        this.businessId = businessId;
    }

    public Long getCreatedBy() {
        return createdBy;
    }

    public void setCreatedBy(Long createdBy) {
        this.createdBy = createdBy;
    }

    public Long getCategoryId() {
        return categoryId;
    }

    public void setCategoryId(Long categoryId) {
        this.categoryId = categoryId;
    }

    public Long getCustomerId() {
        return customerId;
    }

    public void setCustomerId(Long customerId) {
        this.customerId = customerId;
    }

    public Long getVendorId() {
        return vendorId;
    }

    public void setVendorId(Long vendorId) {
        this.vendorId = vendorId;
    }

    public String getDescription() {
        return description;
    }

    public void setDescription(String description) {
        this.description = description;
    }

    public LocalDate getTransactionDate() {
        return transactionDate;
    }

    public void setTransactionDate(LocalDate transactionDate) {
        this.transactionDate = transactionDate;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public OffsetDateTime getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(OffsetDateTime createdAt) {
        this.createdAt = createdAt;
    }
}
